def is_prime(num):
    if num < 2:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def prime_fib(n):
    a, b = 0, 1
    count = 0
    while count < n:
        if is_prime(b):
            count += 1
        a, b = b, a + b
    return b
```

